<template>
  <section class="focus-page">
    <div class="hero"><div><p class="eyebrow">DAILY RHYTHM · {{ todayLabel }}</p><h2>把时间，留给重要的事。</h2><p class="sub">专注当下，记录每一个值得被看见的小时。</p></div><div class="hero-orb">{{ totalTodayLabel }}<small>今日专注</small></div></div>
    <div class="grid">
      <div class="main-col">
        <div class="panel tasks-panel"><div class="panel-head"><div><h3>今天做什么</h3><p>点击事项开始计时，完成后自动留下记录</p></div><button class="add" @click="addTask">＋ 新建事项</button></div>
          <div class="task-grid"><button v-for="task in tasks" :key="task.id" class="task" :class="{running: active?.taskId===task.id}" @click="toggle(task)"><input class="color-picker" type="color" v-model="task.color" :style="{backgroundColor:task.color}" @click.stop @change="saveTask(task)" title="选择颜色" /><span class="task-icon" :style="{background:task.color,'--task-color':task.color}">{{ task.icon }}</span><span class="task-name" :style="{'--task-color': task.color}">{{ task.name }}</span><span class="edit-task" @click.stop="renameTask(task)">编辑</span><span class="delete-task" @click.stop="deleteTask(task)">删除</span></button></div></div><div class="panel timeline"><div class="panel-head"><div><h3>今日时间轴</h3></div></div><div v-if="entriesToday.length" class="entries"><div v-for="entry in entriesToday" :key="entry.id" class="entry"><i :style="{background:entry.color}"></i><div><b>{{ entry.name }}</b><span>{{ clock(entry.start) }} — {{ clock(entry.end) }}</span><small v-if="entry.reflection" class="reflection">{{ entry.reflection }}</small></div><strong>{{ formatDuration(entry.durationSec || entry.minutes*60) }}</strong><span class="record-actions"><button @click="editRecord(entry)">修改</button><button class="record-delete" @click="removeRecord(entry)">删除</button></span></div></div><div v-else class="empty">今天的时间轴正在等你写下第一笔 ✦</div></div>
      </div><aside class="side-col"><div class="panel calendar"><div class="cal-top"><button @click="monthOffset--">‹</button><h3>{{ monthTitle }}</h3><button @click="monthOffset++">›</button></div><div class="week"><span v-for="d in week" :key="d">{{ d }}</span></div><div class="days"><span v-for="(day,i) in calendarDays" :key="i" :class="{muted:!day.current, today:day.key===todayKey, selected:day.key===selectedDate, hot:day.minutes>0}" @click="day.current && selectDate(day.key)"><em>{{ day.date }}</em></span></div><div class="legend"><span>少</span><i></i><i></i><i></i><i></i><span>多</span></div></div><div class="panel analysis"><p class="eyebrow">DAILY ANALYSIS</p><h3>{{ selectedDate===todayKey ? "今日" : selectedDate }} · 时间分配</h3><div class="donut" :style="{background:donutStyle}"><div><b>{{ formatDuration(totalTodaySeconds) }}</b><small>总专注</small></div></div><div class="rank"><div v-for="item in dailyBreakdown" :key="item.name"><span><i :style="{background:item.color}"></i>{{ item.name }}</span><strong>{{ formatDuration(item.seconds) }}</strong><em><b :style="{width:item.percent+'%',background:item.color}"></b></em></div><p v-if="!dailyBreakdown.length" class="analysis-empty">选定日期还没有记录</p></div></div><div class="panel insight"><p class="eyebrow">THIS WEEK</p><strong>{{ formatDuration(weekTotalSeconds) }}</strong><span>本周专注时长</span><div class="bars"><i v-for="n in weekBars" :key="n.day" :style="{height:Math.max(8,n.height)+'%'}" :title="n.day+' '+n.minutes+'分钟'"></i></div></div></aside>
    </div>
  <div v-if="active" class="timer-overlay"><div class="timer-modal"><div class="timer-dot"></div><p class="eyebrow">FOCUSING NOW</p><h3>{{ tasks.find(t=>t.id===active.taskId)?.name || '专注事项' }}</h3><strong>{{ liveLabel }}</strong><span>开始于 {{ clock(active.started) }}</span><button class="stop-timer" @click="stopTimer">停止计时</button></div></div><div v-if="showAdd" class="modal-backdrop" @click.self="showAdd=false"><div class="form-modal"><button class="modal-close" @click="showAdd=false">×</button><p class="eyebrow">NEW ACTIVITY</p><h3>添加一个新事项</h3><p class="modal-hint">给这段时间一个名字，之后就可以开始记录。</p><input v-model="newTaskName" autofocus placeholder="例如：阅读、练琴、散步" @keyup.enter="confirmAddTask" /><div class="modal-actions"><button class="cancel" @click="showAdd=false">取消</button><button class="confirm" @click="confirmAddTask">添加事项</button></div></div></div><div v-if="dialog" class="modal-backdrop" @click.self="dialog=null"><div class="form-modal"><button class="modal-close" @click="dialog=null">×</button><p class="eyebrow">{{ dialog==='reflection' ? 'REFLECTION' : dialog==='rename' ? 'EDIT ACTIVITY' : 'REMOVE ACTIVITY' }}</p><h3>{{ dialog==='reflection' ? '记录这一段的感想' : dialog==='rename' ? '修改事项名称' : '确认删除事项？' }}</h3><p class="modal-hint">{{ dialog==='delete' ? '历史时间记录会保留，不会被删除。' : '写下你的内容，保存后会同步到数据库。' }}</p><textarea v-if="dialog==='reflection'" v-model="dialogValue" placeholder="这段时间有什么收获？" rows="4"></textarea><input v-else-if="dialog==='rename'" v-model="dialogValue" @keyup.enter="submitDialog" /><div class="modal-actions"><button class="cancel" @click="dialog=null">取消</button><button class="confirm" @click="submitDialog">{{ dialog==='delete' ? '确认删除' : '保存' }}</button></div></div></div></section>
</template>
<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { listTimeRecords, createTimeRecord, updateTimeRecord, deleteTimeRecord, listTimeTasks, createTimeTask, updateTimeTask, deleteTimeTask } from '../api'
const KEY='singing_expert_focus_v1', now=ref(Date.now()), monthOffset=ref(0), active=ref(null), tasks=ref([{id:'words',name:'英语单词',icon:'Aa',color:'#6c63ff'},{id:'reading',name:'论文阅读',icon:'◒',color:'#ff9f43'},{id:'exercise',name:'运动健身',icon:'✦',color:'#20c997'},{id:'creative',name:'自由创作',icon:'✎',color:'#ef709d'}]), entries=ref([])
const showAdd=ref(false), newTaskName=ref(''), dialog=ref(null), dialogValue=ref(''), dialogTask=ref(null)
const localDateKey=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}, todayKey=localDateKey(new Date()), selectedDate=ref(todayKey), todayLabel=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}), week=['一','二','三','四','五','六','日']
const save=()=>localStorage.setItem(KEY,JSON.stringify(entries.value)), dateKey=localDateKey
const totalTodaySeconds=computed(()=>entriesToday.value.reduce((s,e)=>s+(e.durationSec||e.minutes*60),0)), dailyBreakdown=computed(()=>{const map={};entriesToday.value.forEach(e=>{if(!map[e.name])map[e.name]={name:e.name,seconds:0,color:(tasks.value.find(t=>t.name===e.name)?.color||e.color)};map[e.name].seconds+=(e.durationSec||e.minutes*60)});const total=totalTodaySeconds.value||1;return Object.values(map).sort((a,b)=>b.seconds-a.seconds).map(x=>({...x,percent:Math.round(x.seconds/total*100)}))}), donutStyle=computed(()=>{let start=0;const colors=dailyBreakdown.value.map(x=>{const end=start+x.percent;const v=`${x.color} ${start}% ${end}%`;start=end;return v});return `conic-gradient(${colors.join(',')||'#ececf2 0 100%'})`})
const entriesToday=computed(()=>entries.value.filter(e=>dateKey(e.start)===selectedDate.value).sort((a,b)=>a.start-b.start)), totalToday=computed(()=>entriesToday.value.reduce((s,e)=>s+e.minutes,0)), totalTodayLabel=computed(()=>formatDuration(entriesToday.value.reduce((s,e)=>s+(e.durationSec||e.minutes*60),0)))
const monthTitle=computed(()=>{const d=new Date();d.setMonth(d.getMonth()+monthOffset.value);return d.toLocaleDateString('zh-CN',{year:'numeric',month:'long'})}), calendarDays=computed(()=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+monthOffset.value);const first=(d.getDay()+6)%7, count=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(), out=[];for(let i=0;i<first;i++)out.push({date:'',current:false});for(let n=1;n<=count;n++){const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;out.push({date:n,current:true,key:k,minutes:Math.round(entries.value.filter(e=>dateKey(e.start)===k).reduce((s,e)=>s+(e.durationSec||e.minutes*60),0)/60)})}return out}), weekBars=computed(()=>{const a=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=dateKey(d),seconds=entries.value.filter(e=>dateKey(e.start)===k).reduce((s,e)=>s+(e.durationSec||e.minutes*60),0);a.push({day:d.toLocaleDateString('zh-CN',{weekday:'short'}),seconds,height:seconds/Math.max(3600,...entries.value.map(e=>e.durationSec||e.minutes*60),3600)*100})}return a}), weekHours=computed(()=>Math.round(weekBars.value.reduce((s,e)=>s+e.minutes,0)/60*10)/10), weekTotalSeconds=computed(()=>weekBars.value.reduce((s,e)=>s+e.seconds,0)), liveLabel=computed(()=>formatDuration(Math.floor((now.value-active.value.started)/1000)))
function selectDate(key){selectedDate.value=key}
function parseServerDate(value){
  if (typeof value !== 'string') return value
  return /(?:Z|[+-]\d\d:\d\d)$/.test(value) ? value : `${value}+08:00`
}
function formatDuration(sec){sec=Math.max(0,Math.round(sec));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?`${h}小时 ${String(m).padStart(2,'0')}分 ${String(s).padStart(2,'0')}秒`:m?`${m}分 ${String(s).padStart(2,'0')}秒`:`${s}秒`} function formatMinutes(m){return m<60?`${m} 分钟`:`${Math.floor(m/60)} 小时 ${m%60?m%60+' 分钟':''}`} function clock(t){return new Date(t).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} function todayMinutes(id){return entriesToday.value.filter(e=>e.taskId===id).reduce((s,e)=>s+e.minutes,0)}
function stopTimer(){if(active.value){const task=tasks.value.find(t=>t.id===active.value.taskId);if(task)toggle(task)}}
function toggle(task){if(active.value?.taskId===task.id){const end=Date.now(),durationSec=Math.max(1,Math.round((end-active.value.started)/1000)),minutes=Math.max(1,Math.round(durationSec/60));const reflection=null;entries.value.push({id:end,taskId:task.id,name:task.name,color:task.color,start:active.value.started,end,durationSec,minutes,reflection});createTimeRecord({task_name:task.name,start_at:new Date(active.value.started).toISOString(),end_at:new Date(end).toISOString(),duration_seconds:durationSec,reflection}).catch(()=>{});active.value=null;save()}else{if(active.value)toggle(tasks.value.find(t=>t.id===active.value.taskId));active.value={taskId:task.id,started:Date.now()}}}
async function editRecord(entry){dialogTask.value=entry;dialogValue.value=entry.reflection||'';dialog.value='reflection'}
async function removeRecord(entry){if(!confirm('确定删除这条时间记录吗？'))return;await deleteTimeRecord(entry.id);entries.value=entries.value.filter(e=>e.id!==entry.id)}
function deleteTask(task){dialogTask.value=task;dialog.value='delete'}
function saveTask(task){if(Number.isInteger(task.id))updateTimeTask(task.id,{name:task.name,icon:task.icon,color:task.color}).catch(()=>{})}
function renameTask(task){dialogTask.value=task;dialogValue.value=task.name;dialog.value='rename'}
async function submitDialog(){const task=dialogTask.value;if(dialog.value==='rename'&&dialogValue.value.trim()){task.name=dialogValue.value.trim();if(Number.isInteger(task.id))updateTimeTask(task.id,{name:task.name,icon:task.icon,color:task.color}).catch(()=>{})}else if(dialog.value==='reflection'){const entry=dialogTask.value;const body={task_name:entry.name,start_at:new Date(entry.start).toISOString(),end_at:new Date(entry.end).toISOString(),duration_seconds:entry.durationSec||entry.minutes*60,reflection:dialogValue.value.trim()||null};const row=await updateTimeRecord(entry.id,body);entry.reflection=row.reflection}else if(dialog.value==='delete'){if(active.value?.taskId===task.id)active.value=null;tasks.value=tasks.value.filter(t=>t.id!==task.id);if(Number.isInteger(task.id))deleteTimeTask(task.id).catch(()=>{})}dialog.value=null}
function addTask(){newTaskName.value='';showAdd.value=true}
function confirmAddTask(){const name=newTaskName.value;if(name?.trim()){const palette=['#6c63ff','#ff9f43','#20c997','#ef709d','#3aa0ff'];const color=palette[tasks.value.length%palette.length];const task={name:name.trim(),icon:'＋',color};createTimeTask(task).then(row=>tasks.value.push(row)).catch(()=>tasks.value.push({...task,id:'custom-'+Date.now()}));showAdd.value=false}}
onMounted(async()=>{try{const [rows,dbTasks]=await Promise.all([listTimeRecords(),listTimeTasks()]);entries.value=rows.map(r=>({id:r.id,taskId:r.task_name,name:r.task_name,color:'#6c63ff',start:parseServerDate(r.start_at),end:parseServerDate(r.end_at),durationSec:r.duration_seconds,minutes:Math.max(1,Math.round(r.duration_seconds/60)),reflection:r.reflection}));if(dbTasks.length)tasks.value=dbTasks;else{const defaults=tasks.value.map(({name,icon,color})=>({name,icon,color}));const created=await Promise.all(defaults.map(createTimeTask));tasks.value=created}}catch{try{entries.value=JSON.parse(localStorage.getItem(KEY)||'[]')}catch{}}const t=setInterval(()=>now.value=Date.now(),1000);onUnmounted(()=>clearInterval(t))})
</script>
<style scoped>
