.04em;display:block;color:#5d51d8}.timer-modal span{display:block;color:#969aa6;font-size:12px;margin:8px 0 24px}.stop-timer{width:100%;border:0;border-radius:14px;padding:13px;background:#fa5575;color:#fff;font-weight:700;cursor:pointer}.reflection{display:block;margin-top:9px;padding:9px 12px;max-width:520px;border-left:3px solid #8b80ff;border-radius:8px;background:#f7f6ff;color:#676b79;font-size:13px;line-height:1.6}.reflection:after{content:'感想';display:block;margin-top:3px;color:#a2a5b1;font-size:10px;letter-spacing:.08em}.analysis h3{font-size:15px;margin:4px 0 14px}.donut{width:150px;height:150px;border-radius:50%;margin:10px auto 18px;display:grid;place-content:center}.donut>div{width:94px;height:94px;border-radius:50%;background:#fff;display:grid;place-content:center;text-align:center}.donut b{font-size:16px}.donut small{font-size:10px;color:#999}.rank{display:grid;gap:12px}.rank>div{display:grid;grid-template-columns:1fr auto;gap:7px;font-size:12px}.rank span i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}.rank strong{font-size:11px}.rank em{grid-column:1/3;height:5px;background:#f0f0f4;border-radius:9px;overflow:hidden}.rank em b{display:block;height:100%;border-radius:9px}.analysis-empty{font-size:12px;color:#999;text-align:center}.insight{background:#171d35;color:#fff}.insight strong{font-size:38px;display:block;margin:6px 0}.insight span{font-size:12px;opacity:.6}.bars{height:80px;display:flex;align-items:end;gap:9px;margin-top:25px}.bars i{flex:1;background:linear-gradient(#8e84ff,#5b4fde);border-radius:6px 6px 2px 2px;min-height:6px}.bars i:nth-child(7){background:#ff8bb0}@media(max-width:900px){.grid{grid-template-columns:1fr}.side-col{grid-template-columns:1fr 1fr}}@media(max-width:600px){.hero{padding:25px;}.hero h2{font-size:26px}.hero-orb{width:82px;height:82px;font-size:15px}.task-grid{grid-template-columns:1fr}.side-col{grid-template-columns:1fr}.panel{padding:18px}}
</style>
